return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Catalan','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-06 00:49+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ca','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" guardat.','"%1$s" created. %2$d template updated.'=>'"%1$s" creat. %2$d plantilla actualitzada.' . "\0" . '"%1$s" creat. %2$d plantilles actualitzades.','"%s" created.'=>'"%s" creat.','"product" (replaces "article")'=>'"producte" (substitueix "article")','%1$d chars — good length. %2$s'=>'%1$d caràcters — bona llargada. %2$s','%1$d chars — may be truncated in SERPs (aim for 140–160). %2$s'=>'%1$d caràcters — pot ser truncat en els resultats de cerca (apunta a 140–160). %2$s','%1$d chars — too short (aim for 140–160). %2$s'=>'%1$d caràcters — massa curt (apunta a 140–160). %2$s','%1$d internal, %2$d external.'=>'%1$d intern, %2$d extern.','%1$d of %2$d image(s) missing alt text.'=>'%1$d de %2$d imatges sense text alternatiu.','%d chars — good length.'=>'%d caràcters — bona llargada.','%d external link(s), no internal links. Add internal links to related content.'=>'%d enllaç(s) externs, sense enllaços interns. Afegeix enllaços interns a contingut relacionat.','%d H1 tags found — a page should have exactly one H1.'=>'%d etiquetes H1 trobades — una pàgina hauria de tenir exactament una H1.','%d image(s), all have alt text.'=>'%d imatge(s), totes tenen text alternatiu.','%d language not yet linked'=>'Encara no s\'ha enllaçat %d llengua' . "\0" . 'Encara no s\'han enllaçat %d llengües','%d link updated.'=>'%d enllaç actualitzat.' . "\0" . '%d enllaços actualitzats.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'No s\'ha pogut eliminar automàticament %d arxiu de llengua (DISALLOW_FILE_MODS està activat). Elimina-ho manualment a través del teu servidor o WP-CLI: wp language core uninstall <locale>.' . "\0" . 'No s\'han pogut eliminar automàticament %d arxius de llengua (DISALLOW_FILE_MODS està activat). Elimina\'ls manualment a través del teu servidor o WP-CLI: wp language core uninstall <locale>.','%d locale file removed.'=>'Arxiu de llengua eliminat: %d.' . "\0" . 'Arxius de llengua eliminats: %d.','%d locale pack installed.'=>'%d paquet de llengua instal·lat.' . "\0" . '%d paquets de llengua instal·lats.','%d navigation reference updated.'=>'S\'ha actualitzat la referència de navegació %d.' . "\0" . 'S\'han actualitzat %d referències de navegació.','%d part reference updated.'=>'S\'ha actualitzat la referència de %d part.' . "\0" . 'S\'han actualitzat %d referències de parts.','%d words — below recommended minimum of 300.'=>'%d paraules — per sota del mínim recomanat de 300.','%d words — very thin content. Consider expanding to at least 300 words.'=>'%d paraules — contingut molt escàs. Considera ampliar-lo a almenys 300 paraules.','%d words.'=>'%d paraules.','%s Archive'=>'%s Arxiu','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s està actiu i ja emet JSON-LD de Schema.org. Lingua Forge ha desactivat la seva pròpia sortida de esquema per evitar gràfics en conflicte. A diferència d\'Open Graph — on LF afegeix og:locale a més de la sortida d\'un altre plugin — el esquema no pot ser complementat netament: gràfics JSON-LD duplicats o que es superposen produeixen errors de validació. Desactiva la sortida de esquema al plugin detectat si vols que LF gestioni dades estructurades.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s està actiu i genera el seu propi mapa del lloc. Aquest mapa del lloc és separat del de LF. Tots dos s\'han de presentar a Google Search Console: el mapa del lloc del plugin SEO mostra el teu contingut; el mapa del lloc de LF afegeix els enllaços alternatius multilingües. El mapa del lloc de LF s\'anuncia automàticament en robots.txt.','(avg %.1f hits/block)'=>'(mitjana %.1f encerts/bloc)','(avg %.1f hits/entry)'=>'(mitjana %.1f hits/entrada)','(disabled)'=>'desactivat','(no title) #%d'=>'(sense títol) #%d','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} no tenia enllaços reemplaçables — reescaneja per investigar)','.txt file(s) in the directory'=>'.txt arxiu(s) al directori','/ 100'=>'/ 100','1 H1 ✓ — no H2 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — no s\'han trobat subtítols H2. Afegir H2 millora l\'estructura.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d plantilla(s) localitzada(s) del tema &#8220;%2$s&#8221; es mantenen a la base de dades però actualment estan inactives. Tornaran a activar-se si reactives aquest tema. Per portar les teves traduccions al nou tema, regenerar-les a través de <strong>Configuració → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> enllaç(s) que es poden arreglar automàticament','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> enllaç(s) que necessiten revisió manual','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> camí(s) obsolet(s)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problema(s) de plantilla','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Existeix un arxiu robots.txt físic a la arrel del lloc. El robots.txt virtual de WordPress — i el Sitemap de LF: filtre — són evitats. El mapa del lloc de LF no s\'anuncia als motors de cerca.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepta només arxius .mo compilats. El nom de l\'arxiu ha de seguir el patró {textdomain}-{locale}.mo. Carregar un arxiu amb el mateix nom que un de ja existent el substituirà.','Action'=>'Acció','Actions'=>'Accions','active'=>'actiu','Active Languages'=>'Llengües actives','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Idiomes actius: afegeix cada idioma que vulguis suportar. Cada idioma obté un prefix de URL o un subdomini i una etiqueta hreflang a la secció &lt;head&gt; de la pàgina.','Active Provider'=>'Proveïdor actiu','Add entry'=>'Afegeix entrada','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Afegeix instruccions per millorar el borrador — per exemple, fes-lo més curt, afegeix una secció de conclusió, utilitza un registre més formal, inclou un bloc de preguntes freqüents…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Afegeix instruccions per millorar l\'esborrany — per exemple, fes-lo més curt, afegeix una secció de conclusió, utilitza un registre més formal…','Add new entry'=>'Afegeix una nova entrada','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Afegeix un terme per fila. Tant el terme d\'origen com la representació de destinació són obligatoris. La parella de llengües determina a quines feines de traducció s\'aplica la restricció.','Add Sitemap directive to robots.txt'=>'Afegeix la directiva Sitemap a robots.txt','Add the following line to your robots.txt manually:'=>'Afegeix la següent línia a robots.txt manualment:','Add WooCommerce product tags to Open Graph output'=>'Afegeix etiquetes de producte de WooCommerce a la sortida d\'Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Afegeix un enllaç a la pàgina d\'inici perquè els visitants puguin navegar en el seu idioma.','Administrators only (manage_options)'=>'Només administradors (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Després de canviar la llengua principal, buida els permalinks (secció a sota) perquè s\'actualitzi la rutes d\'URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Després de canviar la configuració de l\'estructura de URL (prefi de camí ↔ subdomini), visita sempre Configuració → Enllaços permanents i fes clic a Desa els canvis per buidar les regles de reescriptura.','AI analysis failed. Please try again.'=>'L\'anàlisi d\'AI ha fallat. Torna-ho a provar.','AI Behaviour Preset'=>'Predefinit de comportament de IA','AI cache cleared. %d entry was removed.'=>'Caché d\'IA esborrada. %d entrada s\'ha eliminat.' . "\0" . 'Caché d\'IA esborrada. %d entrades s\'han eliminat.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Cànon AI: llista de respostes en memòria cau amb comptadors d\'acerts. Esborra tota la memòria cau o les entrades d\'una publicació. Utilitza "Netejar" abans de provar un canvi de traducció — els resultats en memòria cau es retornaran fins que s\'evicte la entrada de memòria cau.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Les funcions d\'AI són opcionals. El ruteig de llengües, hreflang, el commutador de llengües i el sistema de grups de traducció funcionen sense un proveïdor configurat.','AI Limits & Security'=>'Límits i seguretat de la IA','AI provider returned an empty response.'=>'El proveïdor d\'IA ha retornat una resposta buida.','AI Recommendations'=>'Recomanacions d\'AI','AI returned an unexpected response format. Please try again.'=>'L\'AI ha retornat un format de resposta inesperat. Torna-ho a provar.','AI Usage'=>'Ús de IA','AI Usage & Cache'=>'Ús d\'AI i memòria cau','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Apunta a 120–160 caràcters. Deixa-ho buit per utilitzar el fallback de l\'extracte.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Tots els motors de cerca principals — Google, Bing i Yandex — descobreixen automàticament el mapa del lloc mitjançant la directiva Sitemap: en robots.txt. No cal cap acció manual. Els botons de baix envien un ping immediat perquè el motor recarregui el mapa del lloc ara en lloc d\'esperar la seva pròxima revisió programada de robots.txt.','All time'=>'Tot el temps','All types'=>'Tot tipus','Allow editors to lock individual blocks'=>'Permet als editors bloquejar blocs individuals','Allow Gutenberg template-editing mode on post screens'=>'Permet el mode d\'edició de plantilles de Gutenberg a les pantalles de publicació','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'També elimina les assignacions de llengua, relacions de traducció, metadescripcions, glossari i Memòria de Traducció quan s\'elimina el plugin.','Also generate meta description'=>'També genera una descripció meta','Alternative (server-side):'=>'Alternativa (del costat del servidor):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Sempre emet només og:locale i og:locale:alternate. S\'usa quan un altre plugin o tema gestiona el conjunt complet d\'OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Sempre emet el conjunt complet d\'OG + Twitter Card independentment d\'altres plugins. S\'usa només si cap altre plugin emet etiquetes OG.','An unknown error occurred.'=>'S\'ha produït un error desconegut.','Analysis'=>'Anàlisi','Analysis request failed. Please try again.'=>'La sol·licitud d\'anàlisi ha fallat. Torna-ho a provar.','Analyze'=>'Analitza','Analyzing…'=>'S\'està analitzant…','and'=>'i','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'qualsevol','API calls saved by cache'=>'Crides API guardades per memòria cau','API Key'=>'Clau API','API Keys'=>'Claus API','API Keys Tab'=>'Pestanya de claus API','API Response Cache'=>'Memòria cau de respostes API','Appends the following line to your existing robots.txt: %s'=>'Afegeix la següent línia al teu robots.txt existent: %s','Applied ✓'=>'Aplicat ✓','Apply failed — please try again.'=>'Error en l\'aplicació — si us plau, torna-ho a provar.','Apply to Block'=>'Aplicar a Bloc','Apply to Editor'=>'Aplica a l\'Editor','Apply to Footnote'=>'Aplicar a la nota al peu de pàgina','Apply to Meta Description'=>'Aplica a la Meta Descripció','Apply translation'=>'Aplica la traducció','Applying…'=>'Aplicant…','Approximate size'=>'Mida aproximada','Archive'=>'Arxiu','Archive: %s'=>'Arxiu: %s','Article / WebPage'=>'Article / Pàgina web','Article / WebPage — all singular posts and pages'=>'Article / Pàgina web — totes les publicacions i pàgines en singular','Authors and above (edit_published_posts)'=>'Autors i més (edit_published_posts)','Auto (recommended)'=>'Automàtic (recomanat)','Behavior'=>'Comportament','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Comportament: tria el preset d\'AI (Literal, Equilibrat, Creatiu), afegeix instruccions personalitzades a tot el lloc, habilita o deshabilita la traducció automàtica després de desar, i configura la Memòria de Traducció.','Block Content'=>'Contingut de bloc','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Mostra un avís cortès quan la pàgina actual s\'està mostrant en el seu idioma original perquè no existeix traducció per a l\'idioma del visitant. Impulsat pel senyal LINGUAFORGE_LANG_FALLBACK_ACTIVE del router de Lingua Forge — no emet res quan existeix una traducció per a la localització de la sol·licitud.','Block Editor'=>'Editor de blocs','block keywordfallback'=>'falla','block keywordi18n'=>'i18n','block keywordlanguage'=>'idioma','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'traducció','Block locking'=>'Bloqueig de blocs','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patrons de blocs registrats per a tipus de publicació personalitzats. Utilitza el botó de Traducció per produir una variant de llengua. El contingut traduït s\'emmagatzema aquí i pot ser copiat a qualsevol publicació CPT des de l\'inseridor de patrons de l\'editor de blocs o utilitzat com a punt de partida per a un Patró sincronitzat (Bloc reutilitzable).','block titleMissing Translation Notice'=>'Avís de traducció absent','Block translation reuses'=>'Reutilitzacions de traducció de blocs','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Memòria cau de traducció a nivell de bloc compartida entre publicacions. Quan està activat, blocs idèntics (mateix format, parella de llengües i glossari) es serveixen des de la memòria en lloc de tornar a cridar a l\'AI. Configura-ho a Configuració → Comportament.','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Els articles de blog utilitzen Article; tots els altres tipus de publicacions i pàgines utilitzen Pàgina web. Inclou títol, descripció, inLanguage, url, data de publicació, data de modificació, imatge i editor.','Browser language redirect'=>'Redirecció de llengua del navegador','Built-in preset instructions:'=>'Instruccions predefinides integrades:','Bulletize (•-prefixed)'=>'Fes una llista amb punts (•-prefixed)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Emmagatzema en cache els equivalents traduïts a nivell de bloc perquè el contingut reutilitzable (peus de pàgina compartits, barres laterals, acords, seccions legals amb molta plantilla) no pagui una trucada API cada vegada. Quan està activat, el flux de traducció analitza cada publicació en blocs, busca cada bloc a la cache i envia només els blocs no emmagatzemats en cache a l\'IA en una sol·licitud agrupada. Les edicions del glossari i els canvis en el predefinit de compliment invaliden automàticament les traduccions en cache afectades. Veure estadístiques i esborrar la cache a Manteniment.','cached'=>'emmagatzemat','Cached API responses'=>'Respostes API en memòria cau','Cached block translations'=>'Traduccions de blocs en memòria cau','Cancel'=>'Cancel·la','Cannot determine target language from slug.'=>'No es pot determinar l\'idioma de destinació a partir de l\'slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'No es pot escriure al producte %1$d: és una versió traduïda (idioma: %2$s)%3$s. Les dades operatives (preu, estoc, SKU, dimensions) s\'han d\'actualitzar a la font del producte. Resol l\'ID del producte d\'origen mitjançant: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Etiqueta canònica','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita l\'ús de la IA que pot generar el lloc i restringeix quins rols d\'usuari poden activar trucades de IA de pagament. S\'ubica per sobre del límit de taxa per usuari (30 sol·licituds / minut, codificat) que ja protegeix contra bucles descontrolats d\'un sol usuari.','chars'=>'caràcters','Chunk translated'=>'Fragment traduït','Chunk translated to:'=>'Fragment traduït a:','Clear'=>'Esborra','Clear All'=>'Esborra tot','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Esborrar tots els resultats en caché d\'IA? Les sol·licituds futures desencadenaran noves trucades API fins que la caché es reconstruïsca.','Clear API Response Cache'=>'Netejar la memòria cau de respostes API','Clear Debug Files'=>'Neteja els arxius de depuració','Clear hints'=>'Esborra pistes','Clear input'=>'Esborra l\'entrada','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Netejar tota la Memòria de Traducció? Les traduccions futures reconstruiran la memòria cau a mesura que s\'executin.','Clear Translation Memory'=>'Neteja la Memòria de Traducció','Close'=>'Tanca','Close language panel'=>'Tanca el panell de llengües','Close popover'=>'Tanca el popover','Compatibility'=>'Compatibilitat','Compliance Preset'=>'Predefinit de compliment','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Configura un proveïdor d\'AI a Configuració → Clau API per habilitar les recomanacions amb AI.','Content generated'=>'Contingut generat','Content Generator'=>'Generador de contingut','Content ready'=>'Contingut preparat','Contributors and above — default (edit_posts)'=>'Col·laboradors i més — per defecte (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controla quina quantitat de contingut s\'envia a la IA i com de gran pot ser la resposta. Deixa en blanc un camp per utilitzar el valor per defecte integrat (mostrat com a espai reservat). Augmenta aquests valors si es tallen pàgines grans; redueix-los per reduir els costos de l\'API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla el pressupost de tokens i els límits d\'entrada per a la funció Generador de contingut de l\'IA. Deixa els camps en blanc per utilitzar els valors predeterminats integrats.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla què passa quan un administrador elimina el plugin des de Plugins → Plugins instal·lats → Elimina. Els ajustaments del plugin i les memòries AI sempre s\'eliminaran. Les assignacions de llengua i les relacions de traducció es mantenen per defecte perquè una desinstal·lació accidental o una reinstal·lació puguin continuar on ho van deixar.','Conversational'=>'Conversacional','Copied ✓'=>'Copiat ✓','Copy'=>'Copia','Copy failed — please copy the URL manually.'=>'La còpia ha fallat — si us plau, copia l\'URL manualment.','Copy markup'=>'Copia el markup','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Copia l\'URL actual al porta-retalls. Mostra un missatge de "Enllaç copiat" en èxit.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Copia el resultat i enganxa\'l on sigui necessari (per exemple, directament al camp de notes al peu).','Copy to safe storage'=>'Copia a emmagatzematge segur','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'accions JS copy/native/auto: gestionades per LF\'s social-share.js','Could not add entry: source term and target term are required.'=>'No s\'ha pogut afegir l\'entrada: cal el terme d\'origen i el terme de destinació.','Could not copy the file. Check that the uploads folder is writable.'=>'No s\'ha pogut copiar l\'arxiu. Comprova que la carpeta d\'uploads sigui editable.','Could not instantiate the provider.'=>'No s\'ha pogut instanciar el proveïdor.','Could not save the file. Check that the uploads folder is writable.'=>'No s\'ha pogut desar l\'arxiu. Comprova que la carpeta d\'uploads sigui editable.','Could not save the glossary entry.'=>'No s\'ha pogut desar l\'entrada del glossari.','Could not write to robots.txt. Check file permissions.'=>'No s\'ha pogut escriure en robots.txt. Comproveu els permisos del fitxer.','CPT Block Patterns'=>'Patrons de blocs CPT','Create'=>'Crear','Create missing'=>'Crear missing','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Crear traduccions per al tipus de publicació "%s" requereix una integració activa. Assegureu-vos que la integració requerida està instal·lada i activa.','Creating…'=>'Creant…','Creative / Marketing'=>'Creatiu / Màrqueting','Creative / Marketing instructions'=>'Instruccions creatives / de màrqueting','Current content (will be overwritten)'=>'Contingut actual (s\'escriurà per sobre)','Current status'=>'Estat actual','Current title'=>'Títol actual','Current: {current}'=>'Actual: {current}','Currently emitting'=>'Actualment emetent','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Actualment heretat de la constant %s. Seleccionar un valor aquí el substituirà.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Actualment s\'ignora per a publicacions que utilitzen espais reservats d\'atribut de comentari de bloc (campos wp:details, resum, etc.) — passen a la ruta de traducció de trucada única existent.','Currently:'=>'Actualment:','Custom'=>'Personalitzat','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Quota diària d\'IA assolida (%1$d sol·licituds). Es reinicia a les %2$s UTC.','Daily request limit'=>'Límit diari de sol·licituds','Danger Zone'=>'Zona de perill','Debug Files'=>'Arxius de depuració','Debug files cleared. %d file was removed.'=>'Arxius de depuració eliminats. %d arxiu s\'ha eliminat.' . "\0" . 'Arxius de depuració eliminats. %d arxius s\'han eliminat.','Debug logging'=>'Depuració','Debug logging disabled.'=>'Registre de depuració desactivat.','Debug logging enabled.'=>'Registre de depuració activat.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Depuració: habilita el registre de depuració per capturar les instruccions d\'AI i les respostes API en un fitxer local. Desactiva després de solucionar problemes — el mode de depuració escriu un fitxer en cada sol·licitud d\'AI.','Default OG image'=>'Imatge OG per defecte','Delete'=>'Eliminar','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Eliminar tots els arxius .txt del directori de depuració? El directori en si romandrà perquè les futures escriptures de depuració també s\'hi puguin guardar.','Delete all files for this override (both .mo and .po)?'=>'Eliminar tots els arxius d\'aquesta substitució (tant .mo com .po)?','Delete content data on uninstall'=>'Eliminar dades de contingut en desinstal·lació','Delete this glossary entry?'=>'Voleu eliminar aquesta entrada de glossari?','Describe what to write — topic, key points, structure…'=>'Descriu què vols escriure — tema, punts clau, estructura…','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Detecta plugins SEO actius (Yoast, Rank Math, etc.) en temps d\'execució. Emiteix només og:locale + og:locale:alternate quan un altre plugin ja emet el conjunt complet d\'OG; emet el conjunt complet quan cap no és detectat.','Directory'=>'Directori','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Desactiva durant l\'ajustament de les instruccions o quan necessites que cada sol·licitud arribi al proveïdor d\'AI. La desactivació no elimina les entrades en memòria cau — tornar a activar-les les restaura. Incrementar la despesa API immediatament en llocs ocupats és previsible quan està desactivat.','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Desactivar només per a llocs sense cap ni implementacions completament personalitzades de hreflang. Quan està desactivat, LF ja no elimina la etiqueta canònica del nucli de WordPress i ja no suprimeix la sortida hreflang del plugin SEO.','Disabled'=>'Desactivat','Disabled (by setting)'=>'Desactivat (per configuració)','Disabled (mode setting)'=>'Desactivat (per configuració de mode)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Desactivat perquè el plugin secundari lf-social-share ja proporciona aquesta funció.','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS està configurat.','Display'=>'Mostra','Displays the Lingua Forge language switcher.'=>'Mostra el selector d\'idioma de Lingua Forge.','Do not output any OG tags.'=>'No mostrar cap etiqueta OG.','Documentation'=>'Documentació','Done'=>'Fet','Done — {done} of {total} post(s) fixed.'=>'Fet — {done} de {total} publicacions arreglades.','Down'=>'Cap avall','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Descarrega i instal·la un paquet de llengua del nucli de WordPress directament des de WordPress.org. Un cop instal·lat, la llengua esdevé disponible per a la ruta d\'URL i el flux de treball de traducció AI. La llista de llengües disponibles es recupera a demanda — fes clic al botó de sota per carregar-la.','Dropdown direction'=>'Direcció del desplegable','edit'=>'editar','Editors and above (edit_others_posts)'=>'Editors i més (edit_others_posts)','Enable API response caching'=>'Habilita la memòria cau de respostes API','Enable block-level translation cache reuse across posts'=>'Permet reutilitzar la cache de traducció a nivell de bloc entre publicacions','Enable Social Share URL rewriting for Social Icons blocks'=>'Habilita la reescriptura de l\'URL de Social Share per als blocs d\'Icones Socials','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Introdueix la teva clau API per a almenys un proveïdor d\'AI. Les claus estan xifrades en repòs mitjançant AES-256-GCM amb un secret específic del lloc (LINGUAFORGE_SECRET). No comparteixis exportacions de base de dades sense rotar primer el secret.','environment variable'=>'variable d\'entorn','Error'=>'Error','Expand'=>'Amplia','Expected: {expected}'=>'S\'esperava: {expected}','External share services'=>'Serveis d\'intercanvi externs','Extra guidance — tone, style, constraints, target audience…'=>'Orientació extra — to, estil, restriccions, públic objectiu…','Extra guidance — tone, style, constraints…'=>'Orientació extra — to, estil, restriccions…','Failed. Please try again.'=>'Error. Torna-ho a provar.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'URL d\'imatge de reserva utilitzada quan una pàgina no té imatge destacada, logotip del lloc o icona del lloc. Es mostra en previsualitzacions socials per arxius, l\'índex del blog i qualsevol pàgina singular sense miniatura.','Feature'=>'Funció','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Les funcions es agrupen en dues categories. Introdueix l\'identificador exacte del model per a cada categoria i proveïdor. Deixa un camp en blanc per utilitzar el predeterminat integrat (mostrat com a espai reservat). Només s\'invoca el model del proveïdor actiu en temps d\'execució — configura els altres prèviament si planejes canviar.','File copied to safe storage successfully.'=>'Arxiu copiat a l\'emmagatzematge segur correctament.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Les modificacions de fitxers estan desactivades (DISALLOW_FILE_MODS).','Files'=>'Arxius','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Els arxius es guarden al directori de sota. Útil per diagnosticar problemes de traducció — desactiva-ho un cop tinguis el que necessites perquè els arxius no s\'acumulin. També pots forçar-ho des de wp-config.php amb `define( \'LINGUAFORGE_AI_DEBUG\', true );` que sobreescriu el commutador.','Filter'=>'Filtre','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtra per idioma i tipus de publicació, navega pel teu contingut i fes clic a Analitza en qualsevol element per executar una auditoria SEO basada en regles — longitud del títol, meta descripció, comptador de paraules, estructura de títols, cobertura de text alternatiu d\'imatges i enllaços interns.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra amb linguaforge_debug_dir per redirigir la sortida de depuració a una ubicació no pública.','Finding'=>'Troballa','Fix'=>'Reparar','Fix All'=>'Arregla tot','Fix all links'=>'Arregla tots els enllaços','Fix all parts'=>'Arregla totes les parts','Fix Links'=>'Corregir enllaços','Fix Nav'=>'Corregir navegació','Fix Parts'=>'Corregir parts','Fix Template'=>'Arregla la plantilla','Fixing {n} / {total}…'=>'Arreglant {n} / {total}…','Fixing…'=>'Arreglant…','Flush Permalink Rules'=>'Buida les regles de permalinks','Flush Permalinks'=>'Buida els permalinks','Flush Sitemap Cache'=>'Buida la memòria cau del mapa del lloc','Footnote Content'=>'Contingut de la nota al peu de pàgina','footnote(s) translated — applied together with content.'=>'Notes al peu traduïdes — aplicades juntament amb el contingut.','Footnotes'=>'Notes al peu','Footnotes payload (advanced)'=>'Càrrega de notes a peu de pàgina (avançat)','Forbidden'=>'Prohibit','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçat a OFF per la constant LINGUAFORGE_AI_DEBUG a wp-config.php. Elimina aquesta línia per controlar aquest commutador des d\'aquí.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçat a ON per la constant LINGUAFORGE_AI_DEBUG a wp-config.php. Elimina aquesta línia per controlar aquest commutador des d\'aquí.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Força la regeneració del mapa del lloc en la propera sol·licitud. S\'utilitza després d\'importacions massives o edicions manuals de relacions de traducció.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'S\'han trobat {parts} en <strong>{total}</strong> de <strong>{scanned}</strong> publicacions escanejades per a <strong>{lang}</strong>.','From'=>'De','Front Page'=>'Pàgina principal','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Localització FSE: esbossar, traduir i arreglar enllaços a les plantilles i parts de plantilla de l\'Edició Completa del lloc directament des d\'aquesta pestanya.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Les plantilles FSE s\'inicialitzen des del tema actiu. Crea-les i personalitza-les al Editor del lloc.','Full'=>'Completa','Full Article'=>'Article complet','Full post'=>'Publicació completa','General'=>'General','Generate'=>'Genera','Generate Content'=>'Genera contingut','Generate content…'=>'Genera contingut…','Generate Excerpt'=>'Generar extracte','Generate Meta Description'=>'Generar descripció meta','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Genera el mapa del lloc multilingüe a /lf-sitemap.xml','Generated Content'=>'Contingut generat','Generated meta description'=>'Meta descripció generada','Generating…'=>'Generant…','Generation failed.'=>'Error en la generació.','Getting started'=>'Començar','Global AI preset'=>'Predefinit global d\'IA','Global default (%s)'=>'Per defecte global (%s)','Glossary'=>'Glosari','Glossary entry added.'=>'Entrada de glossari afegida.','Glossary entry removed.'=>'Entrada de glossari eliminada.','Glossary Tab'=>'Pestanya de glossari','Google (Gemini)'=>'Google (Gemini)','Headings'=>'Títols','Hide'=>'Amaga','Hints'=>'Pistes','Home link text'=>'Text de l\'enllaç a l\'inici','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Com hauria de aparèixer en la traducció. Escriu el mateix valor que el terme d\'origen per instruir la IA a conservar-lo literalment.','How to use'=>'Com utilitzar','Hreflang'=>'Hreflang','Hreflang output'=>'Sortida hreflang','Hreflang settings saved.'=>'Configuracions hreflang desades.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Icona + etiqueta','Icon only'=>'Només icona','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Si està marcat, la desinstal·lació del plugin eliminarà permanentment totes les assignacions de llengua, relacions de traducció, metadescripcions, presets per pàgina, el glossari AI i la Memòria de Traducció de cada publicació d\'aquest lloc. Això no es pot desfer. Deixa-ho desmarcat a menys que estiguis eliminant completament el suport multilingüe del lloc.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Si tens un plugin SEO general instal·lat, aquest panell mostra com LF s\'adapta per evitar sortida duplicada. L\'objectiu és evitar col·lisions — no cooperació. LF sempre proporciona la capa SEO multilingüe (hreflang, og:locale, esquema inLanguage) que requereix coneixement de la configuració de rutes de LF per produir correctament.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Si tens instal·lat Yoast SEO, Rank Math, All in One SEO o SEOPress, Lingua Forge els detecta i s\'adapta per evitar sortida duplicada. Per a hreflang, LF s\'hipoteca completament i suprimeix la sortida del plugin perquè aquests plugins no poden produir hreflang correcte per a una configuració de rutes multilingüe. Per a Open Graph, LF afegeix només og:locale i og:locale:alternate — els senyals multilingües que el plugin no pot proporcionar — i deixa el conjunt OG base al plugin. Per a Schema.org, LF desactiva completament la seva pròpia sortida per evitar conflictes en els gràfics JSON-LD.','Images'=>'Imatges','Improve writing'=>'Millora l\'escriptura','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'En l\'editor de blocs, afegeix un bloc d\'Icones Socials. Per a cada icona, obre la configuració de l\'enllaç i introdueix un dels valors "share:" a continuació com a URL. A la part frontal, LF el substitueix per la URL de compartició correcta per a la pàgina actual.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Inclou nom, descripció, inLanguage, url, imatge, i una Oferta amb preu, monedaPreu i disponibilitat. El preu i la disponibilitat provenen del producte de l\'idioma font (model d\'estoc compartit).','Includes site name, url, and inLanguage.'=>'Inclou nom del lloc, url i inLanguage.','Informative'=>'Informatiu','Input tokens'=>'Tokens d\'entrada','Install'=>'Instal·la','Install a Language'=>'Instal·la una llengua','Installed SEO plugins'=>'Plugins SEO instal·lats','Installing…'=>'Estan instal·lant…','instock / oos / pending from WC stock status'=>'en stock / fora d\'estoc / pendent des de l\'estat de stock de WC','Instructions (optional)'=>'Instruccions (opcional)','Instructions / key points'=>'Instruccions / punts clau','Integration API'=>'API d\'integració','Internal Link Fixer'=>'Arreglador d\'enllaços interns','Introduction only'=>'Només introducció','Invalid file reference.'=>'Referència d\'arxiu no vàlida.','Invalid filename.'=>'Nom de fitxer no vàlid.','Invalid language code.'=>'Codi d\'idioma no vàlid.','Invalid language.'=>'Idioma no vàlid.','Invalid locale code.'=>'Codi de llengua no vàlid.','Invalid or primary language.'=>'Idioma no vàlid o principal.','Invalid post ID.'=>'ID de publicació no vàlid.','Invalid post type.'=>'Tipus de publicació no vàlid.','Invalid template part.'=>'Part de plantilla no vàlida.','Invalid template type.'=>'Tipus de plantilla no vàlid.','JavaScript-powered actions'=>'Accions amb JavaScript','Key points, ideas, or structure to build from…'=>'Punts clau, idees o estructura a partir de la qual construir…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Les claus API s\'encripten amb AES-256-CBC abans de ser emmagatzemades a la base de dades de WordPress. El secret d\'encriptació es deriva dels salts d\'autenticació de WordPress (wp-config.php), de manera que les claus en text pla mai no toquen la base de dades.','Language'=>'Idioma','Language %s installed successfully.'=>'La llengua %s s\'ha instal·lat correctament.','Language (optional)'=>'Idioma (opcional)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'La instal·lació de llengües està desactivada en aquest servidor (DISALLOW_FILE_MODS està establert).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'La instal·lació de llengües està desactivada en aquest servidor. La constant DISALLOW_FILE_MODS està establerta en wp-config.php. Installa els paquets de llengua manualment via WP-CLI: wp language core install ca_DE','Language label'=>'Etiqueta d\'idioma','Language Overrides'=>'Sobreescriptures de llengua','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Anul·lacions de llengua: gestiona arxius personalitzats .po/.mo per a les cadenes de la interfície d\'usuari de Lingua Forge. Utilitza això en lloc d\'editar directament els arxius del complement — les anul·lacions sobreviuen a les actualitzacions.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'La instal·lació del paquet de llengua ha fallat. La llengua ja pot estar instal·lada, el codi de llengua pot ser incorrecte, o el teu servidor pot bloquejar l\'escriptura de fitxers.','Language Setup'=>'Configuració de la llengua','Language Switcher'=>'Selector d\'idioma','Language switcher'=>'Commutador de llengües','Language uninstalled. %d post deleted.'=>'Idioma desinstal·lat. %d publicacions eliminades.' . "\0" . 'Idioma desinstal·lat. %d publicacions eliminades.','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Còpies específiques de la llengua de les parts de la plantilla del tema. Un cop esbós, les plantilles s\'actualitzen per referenciar la part específica de la llengua.','Language:'=>'Idioma:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Llengües actualment conegudes pel router (derivades dels paquets de llengua de WordPress instal·lats més la llengua principal). Instal·la paquets de llengua addicionals a la secció de sota per fer més llengües disponibles per a la ruta i la traducció.','Last 30 days'=>'Els últims 30 dies','Last 7 days'=>'Els últims 7 dies','Last generated: %s'=>'Darrera generació: %s','Lead paragraph (≤60 w)'=>'Paràgraf principal (≤60 paraules)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Deixa un camp de model en blanc per utilitzar el predeterminat integrat per a aquest nivell. El text de marcador de posició mostra quin model s\'utilitzarà.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deixa en blanc per a noms de marca i termes independents de la llengua que s\'han d\'aplicar independentment de la llengua de la qual tradueixes.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deixa en blanc per aplicar aquesta entrada a totes les llengües de destinació — ideal per a noms de marca, abreviatures i termes que s\'han de preservar literalment en totes les traduccions.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deixa en blanc per mantenir la clau existent. Introdueix un valor nou per substituir-la.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deixa en blanc per utilitzar el valor predeterminat integrat. Esborrar una sobrescriptura desada restableix el valor predeterminat a la propera gravació.','Legacy lf-social-share mu-plugin'=>'Plugin secundari legat lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Plugin secundari legat lf-social-share detectat. LF retarda el conjunt OG base al plugin secundari i només emet og:locale + og:locale:alternate. Podeu desactivar el plugin secundari — LF\'s Social Share integrat (SEO → Social Share) i Open Graph cobreixen la mateixa funcionalitat.','Legal / Compliance'=>'Legal / Compliment','Legal / Compliance instructions'=>'Instruccions legals / de compliment','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF sempre afegeix og:locale i og:locale:alternate — els senyals multilingües que cap plugin SEO pot produir correctament. Per al conjunt OG base (og:title, og:description, og:image), LF el mostra quan cap altre plugin està present. Quan s\'instal·la un plugin SEO, LF salta el conjunt base per evitar etiquetes duplicades — no perquè el plugin sigui "millor", sinó perquè la duplicació no aporta valor.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF genera el seu propi mapa del lloc amb alternants xhtml:link per a tots els grups de traducció. Quan s\'instal·la un plugin SEO, aquest genera un mapa del lloc separat — ambdós coexisteixen de manera independent. Envia tots dos a Google Search Console: el mapa del lloc del plugin SEO per a la descoberta de contingut, el mapa del lloc de LF per a senyals de relació de llengua.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF està emetent etiquetes hreflang i ha eliminat la etiqueta canònica del nucli de WordPress en pàgines multilingües.','LF is suppressing hreflang output from: %s'=>'LF està suprimint la sortida hreflang de: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF proporciona hreflang precís per a cada idioma configurat, inclòs x-default. Els plugins SEO generals no tenen accés a la configuració de rutes de LF i produirien hreflang basat en suposicions d\'URL incorrectes. LF suprimeix la seva sortida mitjançant un filtre per evitar col·lisions.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF proporciona JSON-LD multilingüe amb anotacions inLanguage vinculades a la seva configuració de rutes de llengua. Quan s\'instal·la un plugin SEO, LF desactiva completament el seu propi esquema: gràfics JSON-LD duplicats produeixen errors de validació i no hi ha una manera neta de complementar un gràfic existent.','LF provides'=>'LF proporciona','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF elimina la etiqueta canònica del nucli de WordPress en pàgines multilingües perquè les regles de reescriptura amb prefix de llengua del router i el hreflang x-default són els senyals canònics correctes per a un lloc multilingüe. Això evita una doble canònica si també s\'hi inclou un plugin SEO. LF no afegeix la seva pròpia canònica — la rutes de llengua ja fan que cada URL sigui canònic.','Light'=>'Lleuger','Light (default — fast and cost-effective)'=>' Lleuger (per defecte — ràpid i econòmic)','Light (fast and cost-effective — Haiku / Flash)'=>'Llum (ràpid i econòmic — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Llum: s\'utilitza per a descripcions meta i generació d\'extractes — ràpid, de baix cost.','Limit results to pages in the given Lingua Forge language code.'=>'Limita els resultats a pàgines en el codi d\'idioma de Lingua Forge donat.','Limits'=>'Límits','Lingua Forge'=>'Llengua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge afegeix rutes multilingües, traducció amb IA, etiquetes hreflang SEO i un commutador de llengües al teu lloc de WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge afegeix propietats Open Graph específiques de WooCommerce a les pàgines de producte perquè compartir una URL de producte a Facebook, Pinterest i plataformes similars mostri el tipus de producte, preu i disponibilitat correctes.','Lingua Forge AI Tools'=>'Eines d\'IA de Lingua Forge','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge amplia el bloc d\'icones socials del nucli de WordPress amb URLs de compartició dinàmics. Estableix l\'enllaç de qualsevol icona a un valor "share:" i LF el reescriu a la URL de compartició correcta o a l\'acció JavaScript en renderitzar — sense necessitat de codi personalitzat o plugins de tercers.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge genera un mapa del lloc XML dedicat a /lf-sitemap.xml que afegeix enllaços alternatius de llengua per a tot el contingut traduït. Aquest mapa complementa el mapa del lloc del nucli de WordPress i qualsevol mapa del lloc de plugins SEO — no els substitueix.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge és una solució SEO multilingüe completa. No cal cap plugin SEO addicional.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge és una solució SEO multilingüe completa. No cal cap plugin SEO o plugin de mapa del lloc addicional.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge genera etiquetes <link rel="alternate" hreflang> per a cada idioma configurat a cada pàgina, incloent x-default que apunta a l\'idioma original. Aquest és el principal senyal de SEO multilingüe per a Google i altres motors de cerca — no cal cap plugin SEO addicional.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge proporciona metadades Open Graph i Twitter Card perquè les URL compartides mostrin la llengua, títol, descripció i imatge correctes a les plataformes socials.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge proporciona dades estructurades JSON-LD de Schema.org perquè els motors de cerca entenguin el tipus de contingut, la llengua i els metadades. Aquesta és la manera principal de comunicar anotacions inLanguage per a contingut multilingüe a Google i altres rastrejadors.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge restringeix dues funcions de Gutenberg per defecte per mantenir la coherència del comportament editorial entre idiomes. Opta aquí quan necessitis totes les capacitats de Gutenberg / FSE.','Lingua Forge Settings'=>'Configuració de Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge utilitza dues capes de memòria cau independents per evitar crides redundants a l\'API d\'IA. Utilitza les pestanyes a continuació per inspeccionar i gestionar cadascuna.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge utilitza dues categories de models per proveïdor:','Lingua Forge — Quick Translate'=>'Lingua Forge — Traducció ràpida','Lingua Forge — Settings'=>'Lingua Forge — Configuració','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Els mòduls integrats de Compartició Social i Open Graph de Lingua Forge cobreixen tota la funcionalitat que proporciona el mu-plugin, a més de suport multilingüe per a og:locale. Podeu desactivar de manera segura el mu-plugin.','Link copied'=>'Enllaç copiat','link(s)'=>'enllaç(s)','Links'=>'Enllaços','Load available languages'=>'Carrega les llengües disponibles','Load content'=>'Carrega contingut','Loading…'=>'Carregant…','Locale only'=>'Només de la llengua','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Bloquejat — hi ha un plugin SEO conflictiu actiu. Vegeu l\'avís anterior.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate emmagatzema les seves traduccions personalitzades a wp-content/languages/loco/ — una ubicació que pot ser esborrada silenciosament per una actualització del nucli de WP, reinstal·lació del complement, o si Loco Translate mateix és eliminat. Copiar arxius aquí els mou a la carpeta Lingua Forge i18n-overrides, que persisteix a través de tots aquests esdeveniments i s\'carrega automàticament en cada sol·licitud.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copia a emmagatzematge segur','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Capacitat de WordPress més baixa que permet activar les funcions de la IA. Restringir això en llocs amb múltiples autors evita que Col·laboradors o comptes de prova executin trucades de IA de pagament. Sobrescriu per funció mitjançant el filtre linguaforge_required_capability.','Maintenance'=>'Manteniment','Maintenance Tab'=>'Pestanya de manteniment','Make casual'=>'Fes-lo informal','Make concise'=>'Fes-lo concís','Make formal'=>'Fes-lo formal','Mark citations needed'=>'Marca quan cal citar','Max context characters'=>'Màxim de context','Max hints characters'=>'Màxim de caràcters d\'orientació','Max input characters'=>'Caràcters d\'entrada màxims','Max output tokens'=>'Tokens màxims de sortida','Maximum characters accepted from the input field. Default: 8 000.'=>'Nombre màxim de caràcters acceptats des del camp d\'entrada. Per defecte: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Nombre màxim de caràcters del contingut de la publicació existent passats a l\'IA com a context de llavor quan no es proporcionen orientacions. Per defecte: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Nombre màxim de caràcters llegits des del camp d\'orientacions. Per defecte: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Nombre màxim de caràcters del contingut de la publicació enviats a l\'IA. 0 significa sense límit — sempre s\'envia el contingut complet (recomanat). Estableix un valor diferent de zero només si el teu proveïdor té una finestra de context ajustada. Es mostra una advertència al registre d\'errors de PHP cada vegada que es retalla el contingut.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Nombre màxim de tokens que la IA pot produir en una sola resposta de traducció. Si una traducció es talla silenciosament al final, augmenta aquest valor. Per defecte: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Nombre màxim de tokens que l\'IA pot produir per execució de generació. Augmenta aquest valor si s\'estan tallant articles complets. Per defecte: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Nombre màxim de tokens que l\'IA pot produir per traducció ràpida. Per defecte: 2.000.','Meta Description'=>'Meta descripció','Meta description'=>'Meta descripció','Meta Description, Excerpt Generator'=>'Meta Descripció, Generador d\'Excerpts','Metric'=>'Mètrica','Minimum role'=>'Rol mínim','Missing pattern name or language.'=>'Falta el nom del patró o l\'idioma.','Mode'=>'Mode','Model'=>'Model','Model tier'=>'Nivell de model','Models'=>'Models','Models Tab (General)'=>'Pestanya de models (General)','Modified'=>'Modificat','Most recent cached block'=>'Bloc en memòria cau més recent','Most recent cached response'=>'Resposta en memòria cau més recent','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Enrutament multilingüe, etiquetes meta SEO i eines de contingut amb IA per a WordPress. Combina detecció de llengua, enrutament d\'URL, hreflang, descripcions meta i funcions d\'extracte, meta i traducció amb IA.','Name displayed in this language. Leave empty to use the source name.'=>'Nom mostrat en aquesta llengua. Deixa-ho en blanc per utilitzar el nom original.','Navigation'=>'Navegació','Navigation has no content to translate.'=>'La navegació no té contingut per traduir.','Navigation not found.'=>'Navegació no trobada.','Navigation posts are translated via the Router tab, not this button.'=>'Les publicacions de navegació es tradueixen a través de la pestanya Router, no amb aquest botó.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traducció de navegació requereix un proveïdor d\'AI actiu. Configura una clau API a la pestanya de Claves API.','Navigations'=>'Navegacions','Network error — could not reach the WordPress AJAX endpoint.'=>'Error de xarxa — no s\'ha pogut arribar a l\'endpoint AJAX de WordPress.','No %s version found in this translation group.'=>'No s\'ha trobat cap versió de %s en aquest grup de traduccions.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'No cal cap acció. Google va descontinuar el seu punt final de ping del mapa del lloc a gener de 2024 i ara descobreix els mapes del lloc exclusivament mitjançant la directiva Sitemap del robots.txt — que ja ha configurat LF. Google ho detectarà en la seva propera exploració.','No AI provider configured.'=>'Cap proveïdor d\'IA configurat.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Cap proveïdor d\'IA configurat. Afegeix una clau API a Configuració → Claves API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'No s\'ha registrat cap ús d\'IA en la finestra seleccionada (%s). Selecciona un rang més ampli a dalt.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Encara no s\'ha registrat cap ús d\'IA. Un cop un editor executa una traducció, genera una meta descripció o utilitza qualsevol altra funció d\'IA, els totals apareixeran aquí.','No API key configured for this provider.'=>'No hi ha cap clau API configurada per a aquest proveïdor.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'No hi ha instruccions predefinides — cada funció d\'IA utilitza els seus propis valors per defecte ajustats. Omple el camp d\'instruccions personalitzades a continuació per afegir les teves pròpies regles per tot el lloc.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'No s\'han detectat plugins SEO conflictius. Lingua Forge gestiona tota la sortida SEO de manera independent.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Encara no s\'han trobat arxius personalitzats de Loco Translate. Apareixen aquí un cop guardes una traducció a Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'No s\'ha detectat cap plugin OG extern. LF està generant el conjunt complet d\'OG + Twitter Card.','No file was selected.'=>'No s\'ha seleccionat cap arxiu.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Cap entrada de glossari coincideix amb el filtre actual. Esborra el filtre per veure totes les entrades, o afegeix-ne una de nova a continuació.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Encara no hi ha entrades de glossari. Afegeix-ne una a continuació per començar a aplicar terminologia en les traduccions.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'No s\'ha trobat cap H1. Normalment, el títol de la publicació és l\'H1 — verifica que el teu tema el generi.','No images found in content.'=>'No s\'han trobat imatges al contingut.','No internal links found to update.'=>'No s\'han trobat enllaços interns per actualitzar.','No language-specific template parts found to map.'=>'No s\'han trobat parts de plantilla específiques d\'idioma per mapar.','No LF meta description set — using excerpt/content.'=>'No s\'ha configurat cap meta descripció de LF — s\'utilitza l\'extracte/contenit.','No links found. Internal links improve crawlability and user navigation.'=>'No s\'han trobat enllaços. Els enllaços interns milloren la rastreabilitat i la navegació de l\'usuari.','No meta description found. Generate one via the AI meta description feature.'=>'No s\'ha trobat cap meta descripció. Genera\'n una mitjançant la funció de meta descripció amb IA.','No navigation references needed updating.'=>'No cal actualitzar referències de navegació.','No override files uploaded yet.'=>'Encara no s\'han carregat arxius de substitució.','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'No s\'ha trobat cap fitxer robots.txt físic. WordPress el genera virtualment i la directiva Sitemap de LF s\'inclou automàticament.','No published posts found for the selected filters.'=>'No s\'han trobat publicacions publicades amb els filtres seleccionats.','No response from AI provider. Check your API key and try again.'=>'No hi ha resposta del proveïdor d\'IA. Comprova la teva clau API i torna-ho a provar.','No response from provider — check the error log for details.'=>'No hi ha resposta del proveïdor — revisa el registre d\'errors per a més detalls.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Cap llengua secundària configurada. Instal·la un paquet de llengua a dalt per habilitar l\'esquelet de la plantilla.','No source content found to translate.'=>'No s\'ha trobat contingut d\'origen per traduir.','No source page linked yet.'=>'Encara no hi ha cap pàgina font enllaçada.','No template part references needed updating.'=>'No cal actualitzar referències de parts de plantilla.','No title set.'=>'No s\'ha establert cap títol.','No translated content found. The sitemap will populate once posts have been translated.'=>'No s\'ha trobat contingut traduït. El mapa del lloc s\'omplirà un cop s\'hagin traduït les publicacions.','No translation found — analyzed the source language version.'=>'No s\'ha trobat cap traducció — s\'ha analitzat la versió en llengua original.','No {lang} translation registered (TRID missing)'=>'No hi ha cap traducció en {lang} registrada (TRID falta)','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Encara no s\'ha generat. El mapa del lloc es construeix en la primera visita a l\'URL del mapa del lloc i s\'emmagatzema en memòria cau durant 24 hores.','Notes'=>'Notes','Nothing — all types disabled'=>'Res — tots els tipus estan desactivats','Notice message'=>'Missatge d\'avís','Notice settings'=>'Configuració de l\'avís','Notify search engines'=>'Notifica els motors de cerca','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Etiquetes OG/Twitter Card: gestionat pel mòdul Open Graph de LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Bloc en memòria cau més antic','Oldest cached response'=>'Resposta en memòria cau més antiga','Only .mo files are accepted.'=>'Només s\'accepten arxius .mo.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Targetes Open Graph i Twitter','Open Graph output'=>'Sortida d\'Open Graph','Open Graph settings saved.'=>'Configuració d\'Open Graph desada.','Open Search Console →'=>'Obre la Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Obre la safata de compartir web nativa del navegador (iOS, Android, alguns escriptoris). Torna a copiar al porta-retalls si no és compatible.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Context opcional per a editors (p. ex. "ASIC = Circuit Integrat Específic per a Aplicacions; conservar en anglès en contexts tècnics").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opcional. Bing ja llegeix la directiva Sitemap: del robots.txt — això només desencadena una nova rastrejada immediata en lloc d\'esperar la propera revisió programada.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opcional. Yandex ja llegeix la directiva Sitemap: del robots.txt — això només desencadena una nova rastrejada immediata en lloc d\'esperar la propera revisió programada.','Output'=>'Sortida','Output Article or WebPage schema on singular posts and pages'=>'Mostra l\'esquema Article o WebPage en publicacions i pàgines singulars','Output hreflang tags in wp_head'=>'Mostra les etiquetes hreflang a wp_head','Output mode'=>'Mode de sortida','Output Open Graph tags in wp_head'=>'Mostra les etiquetes Open Graph a wp_head','Output Product schema on WooCommerce product pages'=>'Mostra l\'esquema Producte a les pàgines de producte de WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Sortida Schema.org JSON-LD a wp_head','Output tokens'=>'Tokens de sortida','Output WebSite schema on the front page and blog index'=>'Sortida de l\'esquema WebSite a la pàgina principal i a l\'índex del blog','Overall SEO score'=>'Puntuació global de SEO','overridden'=>'sobreescrit','Override file deleted.'=>'Arxiu de substitució eliminat.','Override file uploaded successfully.'=>'Arxiu de substitució carregat correctament.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobreescriu el predefinit de IA per a la traducció i la generació de contingut en aquesta pàgina. Totes les altres funcions sempre utilitzen el predefinit global.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobreescriu el predefinit de IA per a la traducció i la generació de contingut en aquesta pàgina. Les instruccions personalitzades globals (Configuració → Comportament) sempre s\'afegeixen a cada sol·licitud independentment d\'aquesta selecció.','Overview'=>'Visió general','Page'=>'Pàgina','Part'=>'Part','Paste a footnote, sentence, or any snippet here…'=>'Enganxa una nota a peu de pàgina, una frase o qualsevol fragment aquí…','Paste text, or select text in the editor first…'=>'Enganxa text, o selecciona primer el text a l\'editor…','Paste text, or select text on the page first…'=>'Enganxa text, o selecciona primer el text a la pàgina…','Paste your API key…'=>'Enganxa la teva clau API…','Path prefix — example.com/de/'=>'Prefix de camí — example.com/ca/','Pattern'=>'Patró','Pattern has no content to translate.'=>'El patró no té contingut per traduir.','Pattern not found.'=>'Patró no trobat.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'El patró ha estat traduït i desat. Copia el contingut al teu publicació CPT mitjançant l\'inseridor de patrons de l\'editor de blocs o utilitza\'l com a punt de partida per a un bloc reutilitzable.','Pattern translation failed.'=>'La traducció del patró ha fallat.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Càlcul en memòria cau per a cada publicació per a traduccions generades per IA, metadescripcions, extractes i contingut. Sempre actiu — no cal commutador separat. Les entrades s\'invaliden automàticament quan canvia el contingut o el proveïdor/model d\'IA.','Permalink rules flushed successfully.'=>'Les regles de permalinks s\'han buidat correctament.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Elimina permanent totes les plantilles, parts de plantilla, patrons, menús de navegació, publicacions, pàgines, tipus de publicació personalitzats, productes i variacions de productes associats amb aquest idioma. També elimina els arxius del paquet de localització de WordPress perquè aquest idioma ja no aparegui al router. Aquesta acció no es pot desfer.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Eliminar permanentment %s? Això eliminarà tot el contingut traduït per a aquest idioma i no es pot desfer.','Permission denied.'=>'Permís denegat.','Persuasive'=>'Persuasiu','PHP constant'=>'constant PHP','Pin on Pinterest'=>'Pin on Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Fixa termes que no s\'han de traduir o que sempre s\'han de representar d\'una manera específica (per exemple, noms de marca, noms de productes, acrònims). Les restriccions del glossari s\'injecten a cada sol·licitud de traducció d\'IA per a totes les funcions: traducció de publicacions, descripcions meta, extractes i traducció de plantilles FSE.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Llenguatge senzill','Please enter some instructions first…'=>'Primer introdueix algunes instruccions…','Please enter some text first…'=>'Primer introdueix algun text…','Plugin'=>'Plugin','Post'=>'Publicació','Post not found or not published.'=>'Publicació no trobada o no publicada.','Post not found.'=>'Publicació no trobada.','Post on X / Twitter'=>'Publica a X / Twitter','Post Types'=>'Tipus de publicació','Prefilled from excerpt. Edit to override.'=>'Omplert a partir de l\'extracte. Edita per sobreescriure.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'El preu i la disponibilitat sempre reflecteixen el producte de l\'idioma original (model d\'estoc compartit). Les etiquetes només s\'emeten quan el mòdul Open Graph de LF està configurat a "Completo" o "Automàtic" sense cap conflicte amb el plugin SEO.','Primary Language'=>'Llengua principal','Primary language'=>'Llengua principal','Primary language saved.'=>'Llengua principal guardada.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Llengua principal: la llengua en què està escrit el contingut existent. Totes les traduccions es produeixen a partir d\'aquesta llengua; canviar-la no mou ni elimina cap publicació.','Processing…'=>'Processant…','Product'=>'Producte','Product Open Graph'=>'Open Graph del producte','Product — WooCommerce product pages'=>'Producte — pàgines de producte de WooCommerce','Provider'=>'Proveïdor','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'El proveïdor no ha retornat cap text. Comprova el registre d\'errors de WordPress per a la raó detallada de la fallada.','Quality'=>'Qualitat','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualitat (per defecte — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>' Qualitat (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Qualitat: s\'utilitza per a la traducció de publicacions i la generació de contingut — qualitat superior, cost més elevat.','Quick Translate'=>' Traducció ràpida','Quick Translation'=>' Traducció ràpida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traducció ràpida s\'utilitza en mode fragment/pedaç — passatges curts traduïts a demanda des de la barra d\'eines, l\'editor o els popovers de blocs. Utilitza una configuració separada i més lleugera de la traducció de pàgina completa per mantenir les respostes ràpides i econòmiques.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Reactiva canLockBlocks de Gutenberg. Útil per a plantilles editorials que necessiten evitar que els col·laboradors moguin o eliminin blocs específics.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Reactiva supportsTemplateMode. Clau per als fluxos de treball de Full-Site-Editing on les sobrescripcions de plantilla a nivell de publicació són intencionades.','Re-generates and updates the cached result.'=>'Regenere i actualitza el resultat emmagatzemat.','Re-scan'=>'Re-escannejar','Re-scanning…'=>'Reescanejant…','Re-translate'=>'Re-tradueix','Reading time'=>'Temps de lectura','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirigeix els visitants a la seva llengua preferida segons l\'encapçalament Accept-Language del navegador','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Refina més — per exemple, "fes-lo més curt" o "fes servir un to formal"…','Refine further:'=>'Refina més:','Refinement'=>'Refinament','Refinement failed — please try again.'=>'Error en la refinació — si us plau, torna-ho a provar.','Refining…'=>'Refinant…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenera les regles de reescriptura de WordPress perquè els prefixos d\'URL, els slugs específics de la llengua i les reescriptures d\'arxiu estiguin sincronitzats. És necessari després de canviar la llengua principal o afegir suport per a una nova llengua.','Remove stored key'=>'Elimina la clau emmagatzemada','Report an issue on GitHub'=>'Reporta un problema a GitHub','Request failed — please try again.'=>'Error en la sol·licitud — si us plau, torna-ho a provar.','Request failed.'=>'Error en la sol·licitud.','Request failed. Check your connection.'=>'Error en la sol·licitud. Comprova la teva connexió.','Request failed. Please try again.'=>'Error en la sol·licitud. Torna-ho a provar.','Requests'=>'Sol·licituds','Reset'=>'Restableix','Result will appear here…'=>'El resultat apareixerà aquí…','Retranslate'=>'Retradueix','Retranslating…'=>'Retraduint…','Review carefully — links and slugs not updated.'=>'Revisa atentament — enllaços i slugs no actualitzats.','Review translation before applying'=>'Revisa la traducció abans d\'aplicar-la','Revise'=>'Revisa','Revision'=>'Revisió','Revision Type'=>'Tipus de revisió','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt actualitzat amb la directiva Sitemap.','Router'=>'Router','Router Tab'=>'Pestanya de rutes','Run AI Analysis'=>'Executa l\'anàlisi d\'IA','Save Debug Setting'=>' Desa la configuració de depuració','Save Hreflang Settings'=>' Desa la configuració Hreflang','Save Open Graph Settings'=>' Desa la configuració Open Graph','Save Router Settings'=>'Desa la configuració del router','Save Schema.org Settings'=>' Desa la configuració Schema.org','Save Settings'=>'Desa la configuració','Save Sitemap Settings'=>' Desa la configuració del mapa del lloc','Save Social Share Settings'=>' Desa la configuració de compartició social','Save the post to persist changes.'=>' Desa la publicació per guardar els canvis.','Save Uninstall Setting'=>'Desa la configuració de desinstal·lació','Save WooCommerce SEO Settings'=>' Desa la configuració SEO de WooCommerce','Saved to the meta description field when you apply.'=>'S\'ha desat al camp de meta descripció quan s\'aplica.','Scan failed: '=>'Fallada de l\'escaneig: ','Scan request failed. Please try again.'=>'Fallada de la sol·licitud d\'escaneig. Torna-ho a provar.','Scanning posts for broken language links…'=>'Escanejant publicacions per enllaços trencats de llenguatge…','Schema output deferred.'=>'Sortida de Schema ajornada.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'JSON-LD de Schema.org','Schema.org output'=>'Sortida de Schema.org','Schema.org settings saved.'=>'Configuració de Schema.org desada.','Search'=>'Cerca','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Search Console és útil per monitoritzar errors d\'indexació i de cobertura, però no és necessari per a la descoberta.','Search Results'=>'Resultats de la cerca','Security check failed — file path is not permitted.'=>'Fallada en la comprovació de seguretat — el camí de l\'arxiu no està permès.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecciona una llengua per gestionar les seves plantilles FSE, parts de la plantilla i menús de navegació.','Select language'=>'Selecciona llengua','Send via Telegram'=>'Envia via Telegram','Send via WhatsApp'=>'Envia via WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Anàlisi SEO','SEO character-count info'=>'Informació sobre el comptador de caràcters SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Plugins SEO detectats: %s. LF està emetent només og:locale i og:locale:alternate; el plugin detectat gestiona el conjunt complet d\'OG.','SEO plugins and conflict avoidance:'=>'Plugins SEO i evitació de conflictes:','SEO Tab'=>'Pestanya SEO','Server setup (subdomain)'=>'Configuració del servidor (subdomini)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Estableix el comportament predeterminat de l\'IA per a totes les funcions a tot el lloc. Els publicacions individuals poden substituir això per Traducció i Generació de contingut a través de la caixa meta de Lingua Forge.','Settings'=>'Configuració','Settings saved.'=>'Configuració desada.','Share on Facebook'=>'Comparteix a Facebook','Share on LinkedIn'=>'Comparteix a LinkedIn','Share on Mastodon'=>'Comparteix a Mastodon','Share via email (mailto:)'=>'Comparteix per correu electrònic (mailto:)','Show home link'=>'Mostra l\'enllaç a la pàgina d\'inici','Shown when no translation exists for the visitor\'s language.'=>'Mostrat quan no existeix traducció per a l\'idioma del visitant.','Single'=>'Simple','Single %s'=>'Singular %s','Single: %s'=>'Singular: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Límit màxim de sol·licituds de la IA per dia UTC (inclou tant traduccions de la barra d\'eines com revisions de blocs). El comptador es reinicia a la mitjanit UTC. Estableix a 0 per desactivar el límit.','Sitemap'=>'Mapa del lloc','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'La memòria cau del mapa del lloc s\'ha buidat. Es regenerarà en la propera visita a l\'URL del mapa del lloc.','Sitemap output'=>'Sortida del mapa del lloc','Sitemap settings saved.'=>'Configuració del mapa del lloc desada.','Sitemap URL'=>'URL del mapa del lloc','Size'=>'Mida','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Compartició de bloc d\'icones socials: URLs: gestionat pel compartidor social integrat de LF (SEO → Compartir social)','Social Share'=>'Compartir social','Social Share settings saved.'=>'Configuració de compartició social desada.','Some link fixes failed.'=>'Alguns arreglaments d\'enllaços han fallat.','Some nav ref fixes failed.'=>'Alguns arreglaments de referències de navegació han fallat.','Some part fixes failed.'=>'Alguns arreglaments de parts han fallat.','Some parts could not be created.'=>'Algunes parts no s\'han pogut crear.','Some templates could not be created.'=>'Algunes plantilles no s\'han pogut crear.','Some translations failed.'=>'Algunes traduccions han fallat.','source'=>'font','Source file not found.'=>'Arxiu font no trobat.','Source lang'=>'Llengua d\'origen','Source language'=>'Llengua d\'origen','Source term'=>'Termes d\'origen','Standard'=>'Estàndard','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'El mode estàndard utilitza la temperatura ajustada de cada funció: Traducció T=0.2 (precís), Traducció ràpida T=0.4, Generador de contingut T=0.6 (creatiu). Els altres predefinits apliquen una temperatura fixa única a totes les funcions.','Status'=>'Estat','Status / Actions'=>'Estat / Accions','Storytelling'=>'Narració','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Mode de preservació estricta per a contingut legal, regulador, mèdic o tècnic. Quan està activat, cada funció d\'IA utilitza una temperatura de mostreig baixa i afegeix l\'addenda a continuació al seu sistema de prompt — la terminologia, els números d\'article, les unitats, els noms de marca i el llenguatge regulador es preserven textualment en lloc de parafrasejar.','Structured Outline'=>'Esquema estructurat','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'El mode de subdomini requereix que el teu servidor web apunti tots els subdominis de llengua (per exemple, ca.exemple.com) a aquesta instal·lació de WordPress. Després de canviar de mode, buida les regles de permalinks i elimina qualsevol memòria cau. Si la teva URL d\'inici inclou www (per exemple, www.exemple.com), utilitza el filtre lf_base_domain per establir el domini apex sense subdomini perquè els subdominis es construeixin correctament.','Subdomain — de.example.com/'=>'Subdomini — ca.exemple.com/','Submit this URL to Google Search Console alongside your main sitemap.'=>'Envia aquesta URL a Google Search Console juntament amb el vostre mapa del lloc principal.','Submit to Reddit'=>'Envia a Reddit','Suggested meta description'=>'Meta descripció suggerida','Suggested title'=>'Títol suggerit','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Proveïdors compatibles: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Només un proveïdor està actiu a la vegada. Selecciona l\'proveïdor actiu a la pestanya General.','Suppressed: %s.'=>'Supressió: %s.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per funció','Tag'=>'Etiqueta','Tags emitted'=>'Etiquetes emeses','Target lang'=>'Llengua de destinació','Target Language'=>'Llengua de destinació','Target language'=>'Llengua de destinació','Target term'=>'Termes de destinació','Target: 140–160 chars for optimal SERP display'=>'Objectiu: 140–160 caràcters per a una visualització òptima a SERP','Technical'=>'Tècnic','Technical / Scientific'=>'Tècnic / Científic','Technical / Scientific instructions'=>'Instruccions tècniques / científiques','Template "%s" already exists.'=>'La plantilla "%s" ja existeix.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'La plantilla "{expected}" no existeix — crea-la primer al Editor del lloc.','Template has no content.'=>'La plantilla no té contingut.','Template mode'=>'Mode de plantilla','Template not found or not stored in the database.'=>'Plantilla no trobada o no emmagatzemada a la base de dades.','Template part "%s" already exists.'=>'Part de plantilla "%s" ja existeix.','Template part has no content.'=>'La part de plantilla no té contingut.','Template part not found or not stored in the database.'=>'Part de plantilla no trobada o no emmagatzemada a la base de dades.','Template Parts'=>'Parts de la plantilla','Templates'=>'Plantilles','Test connection'=>'Prova de connexió','Testing…'=>'Prova…','Text domain / locale'=>'Àmbit de text / idioma','Text to translate'=>'Text a traduir','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'La memòria cau de respostes API emmagatzema el resultat brut de cada sol·licitud d\'IA — traducció, descripció meta, extracte i generació de contingut — identificat per un hash dels inputs (contingut, parella de llengües, proveïdor, model). Les sol·licituds posteriors amb inputs idèntics es serveixen des de la memòria cau sense cridar a l\'API. La memòria cau és diferent de la Memòria de Traducció: aquesta opera a nivell de bloc i és compartida entre publicacions; la memòria de respostes API opera a nivell de funció i està identificada per publicació.','The editor did not accept the content — please try again.'=>'L\'editor no va acceptar el contingut — si us plau, torna-ho a provar.','The following directive is active in your virtual robots.txt:'=>'La següent directiva està activa en el vostre robots.txt virtual:','The lf-social-share mu-plugin is active.'=>'L\'plugin mu lf-social-share està actiu.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'L\'plugin mu lf-social-share està actiu. La compartició social integrada de Lingua Forge està inactiva — el plugin mu gestiona la reescriptura de URL de compartició i les accions JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'El nivell Lleuger utilitza el model ràpid configurat a la taula de Models anterior (per defecte: Haiku / Flash). Canvia a Qualitat si necessites la mateixa precisió de traducció que en mode de pàgina completa per a fragments.','The phrase as it appears in the source text.'=>'La frase tal com apareix en el text d\'origen.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'La llengua principal sempre s\'ofereix a la ruta arrel del teu lloc — sense prefix URL en mode de ruta, sense subdomini de llengua en mode de subdomini. Totes les altres llengües utilitzen un prefix /lang/ (p. ex. example.com/de/) o un subdomini de llengua (p. ex. de.exemple.com), segons l\'ajust de l\'estructura d\'URL a sota.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'La pestanya SEO → Compatibilitat mostra l\'estat de detecció en viu i explica exactament què fa LF per a cada àrea de funció.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'La URL de compartició sempre reflecteix la pàgina actual — no cal introduir manualment la URL. El filtre linguaforge_social_share_url permet substituir la URL resolta per qualsevol servei.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'El mapa del lloc s\'anuncia automàticament en robots.txt. Tots els motors de cerca principals — Google, Bing, Yandex — el descobreixen des de robots.txt. No cal enviar-lo manualment.','The source page has no footnotes.'=>'La pàgina font no té notes a peu de pàgina.','The upload failed — please try again.'=>'La càrrega ha fallat — torna-ho a provar.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'El mapa del lloc del nucli de WordPress llista totes les URLs del contingut. El mapa del lloc LF indica als motors de cerca com les versions en diferents idiomes es relacionen entre si mitjançant alternants xhtml:link hreflang. Envia\'ls a Google Search Console per a una cobertura completa.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Aquestes notes a peu de pàgina provenen de la pàgina font i es mostren aquí només com a referència. Afegeix-les a aquesta pàgina utilitzant l\'editor de blocs.','This is the source page. Footnotes are edited directly in the block editor.'=>' Aquesta és la pàgina font. Les notes a peu de pàgina s\'editin directament en l\'editor de blocs.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Actualment, aquesta clau és proporcionada per un servidor %s i no es pot eliminar aquí. Introdueix una nova clau a dalt per substituir-la amb un valor de base de dades.','This language is protected and cannot be uninstalled.'=>'Aquest idioma està protegit i no es pot desinstal·lar.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Aquest idioma coincideix amb la configuració regional de WordPress i no es pot desinstal·lar.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Consell: per restablir un model al predeterminat integrat, esborra el camp i desa.','Title'=>'Títol','Title is %d chars — aim for 50–60.'=>'El títol té %d caràcters — apunta a 50–60.','Title is %d chars — may be truncated in SERPs (aim for 50–60).'=>'El títol té %d caràcters — pot ser truncat en els SERPs (apunta a 50–60).','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Per utilitzar un secret de xifratge personalitzat (en lloc del valor derivat wp_salt), afegeix això a wp-config.php:','Today'=>'Avui','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'El consum de tokens s\'agrega per funció, proveïdor i model. S\'enregistra en cada trucada AI exitosa; les proves de connexió s\'exclouen perquè no distorsionin els totals.','Tone'=>'To','tone'=>'to','Tone:'=>'To:','Too many AI requests. Please retry in %d seconds.'=>'Massa sol·licituds d\'IA. Torna-ho a provar en %d segons.','Total'=>'Total','Total tokens'=>'Tokens totals','Translate'=>'Tradueix','Translate / Revise'=>'Tradueix / Revisar','Translate / Revise block'=>'Bloc de traducció / revisió','Translate all'=>'Tradueix tot','Translate chunk'=>'Tradueix el fragment','Translate Content'=>'Tradueix contingut','Translate missing'=>'Falta traducció','Translate page…'=>'Tradueix la pàgina…','Translated content'=>'Contingut traduït','Translated Names'=>'Noms traduïts','Translated title'=>'Títol traduït','Translated to:'=>'Traduit a:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traduit. Revisió a l\'Editor del lloc — els enllaços interns, les URL de navegació i els slugs de les plantilles no s\'actualitzen automàticament.','Translating…'=>'Traduint…','Translation'=>'Traducció','Translation Caching'=>'Caché de traducció','Translation found but permalink could not be generated'=>'S\'ha trobat la traducció però no s\'ha pogut generar el enllaç permanent','Translation Limits'=>'Límits de traducció','Translation Limits & Behavior'=>'Límit de traducció i comportament','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Límits de traducció: controla quins rols d\'usuari poden activar la traducció amb IA i estableix un pressupost mensual de tokens. Superar el pressupost suspèn les trucades a l\'IA fins que el mes es reiniciï.','Translation Memory'=>'Memòria de traducció','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'La memòria de traducció emmagatzema els resultats de l\'IA per hash de contingut, parella de llengües, proveïdor i model. Editar una publicació invalida l\'entrada de la memòria cau perquè la propera traducció obtingui un resultat fresc.','Translation Memory cleared. %d cached block was removed.'=>'Memòria de traducció netejada. %d bloc en caché s\'ha eliminat.' . "\0" . 'Memòria de traducció netejada. %d blocs en caché s\'han eliminat.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Memòria de traducció: emmagatzema la publicació traduïda completa per hash de contingut. Esborra-la quan vulguis forçar una re-traducció de totes les publicacions, independentment de si el seu contingut ha canviat.','Translation workflow'=>'Flux de treball de traducció','Translation, Content Generator'=>'Traducció, Generador de contingut','Type'=>'Tipus','Uli Hake'=>'Uli Hake','Uninstall %s'=>'Desinstal·la %s','Uninstall Behaviour'=>'Desinstal·lar comportament','Uninstall setting saved.'=>'Configuració de desinstal·lació guardada.','unknown error'=>'error desconegut','Unknown provider.'=>'Proveïdor desconegut.','Unknown search engine.'=>'Motor de cerca desconegut.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'A diferència de hreflang — on LF sempre substitueix altres plugins perquè no poden conèixer la vostra configuració multilingüe — Open Graph és diferent: Yoast, Rank Math i plugins similars ja emeten etiquetes OG correctes per al vostre contingut. Duplicar-les no afegeix valor. En mode automàtic, LF detecta plugins SEO actius i afegeix només allò que no poden proporcionar: og:locale (idioma actual) i og:locale:alternate (tots els altres idiomes configurats).','Up'=>'Cap amunt','Upload .mo file'=>'Carrega arxiu .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carrega arxius .mo compilats per substituir les cadenes del complement de tercers per a idiomes específics — per exemple, una traducció personalitzada de VikBooking que utilitza "apartament" en lloc de "habitació". Els arxius han de seguir la convenció de nomenament de WordPress: {textdomain}-{locale}.mo (per exemple, vikbooking-ca.mo). Es guarden a la carpeta d\'uploads i sobreviuen a les actualitzacions del complement.','Upload Override'=>'Carrega substitució','URL could not be mapped to a post — check the link target exists'=>'L\'URL no es va poder mapar a una publicació — comprova que el target de l\'enllaç existeix','URL structure'=>'Estructura d\'URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Estructura de l\'URL: mode de prefix de camí (example.com/de/) no requereix canvis al servidor. Mode de subdomini (de.example.com) requereix un registre DNS comodí, un certificat SSL comodí i un canvi en la configuració del servidor web — consulta la guia de configuració del servidor.','URL to enter'=>'URL per introduir','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Utilitza la compartició nativa quan estigui disponible; recorre a copiar al porta-retalls. Recomanat per als botons de "Compartir".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Utilitza les pestanyes a la part superior d\'aquesta pàgina per configurar cada àrea. Els canvis a la pestanya del router tenen efecte immediat; els canvis a les claus d\'IA i configuracions de model s\'apliquen a la propera sol·licitud d\'IA.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Taula de terminologia gestionada per l\'usuari per parelles de llengües. Les entrades s\'afegeixen a la sol·licitud del sistema de traducció perquè la IA utilitzi termes preferits de manera consistent — crític per al vocabulari del domini ("kWp", "PPA", "punt d\'interconnexió"), noms de marca que no s\'han de traduir, i frases regulatòries estàndard. Els camps de llengua són opcionals: deixa en blanc "Llengua d\'origen" per aplicar l\'entrada independentment de la llengua de la qual tradueixes; deixa en blanc "Llengua de destinació" per aplicar-la a totes les llengües de destinació a la vegada.','Using custom meta description.'=>'Utilitzant meta descripció personalitzada.','Using LF AI meta description.'=>'Utilitzant la meta descripció AI de LF.','Value source'=>'Font del valor','View'=>'Veure','View built-in default'=>'Veure el valor predeterminat integrat','View current robots.txt'=>'Veure el robots.txt actual','View details'=>'Veure detalls','View Lingua Forge details'=>'Veure detalls de Lingua Forge','Visit plugin site'=>'Visita el lloc del plugin','Warning:'=>'Avís:','WebSite'=>'WebSite','WebSite — front page / blog index'=>'WebSite — pàgina principal / índex del blog','What LF provides — and collision avoidance'=>'El que proporciona LF — i evitació de col·lisions','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'El que proporciona LF: etiquetes hreflang per a cada idioma configurat, etiquetes Open Graph i Twitter Card amb og:locale i og:locale:alternate, Schema.org JSON-LD amb anotacions inLanguage, i un mapa del lloc multilingüe dedicat a /lf-sitemap.xml amb entrades xhtml:link alternes per a tots els grups de traducció.','When another SEO plugin is installed'=>'Quan s\'instal·la un altre plugin SEO','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Quan s\'activa el registre de depuració (a través del commutador de sota o definint LINGUAFORGE_AI_DEBUG a wp-config.php), les funcions de traducció i de traducció de plantilles FSE escriuen les seves peticions i respostes d\'AI en brut a disc per a la resolució de problemes. Utilitza aquesta secció per monitoritzar aquesta sortida i netejar-la un cop tinguis el que necessites — els arxius poden créixer ràpidament en pàgines grans. Configura el directori de destinació mitjançant el filtre linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Quan està activat, els visitants que no tenen cookie de llengua i no tenen prefix de llengua a l\'URL són redirigits a la versió de llengua més propera. La redirecció s\'ignora si la llengua preferida del navegador no està entre les llengües actives del router. Un cop un visitant selecciona una llengua mitjançant el commutador, la cookie té prioritat i s\'ignora l\'encapçalament del navegador en futures visites.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Quan està activat, Lingua Forge emet les següents etiquetes meta addicionals a les pàgines de producte: og:type=product, og:price:amount, og:price:currency, og:availability, i els seus equivalents de l\'espai de noms producte utilitzats per Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Quan està activat, l\'URL del mapa del lloc s\'anuncia automàticament en robots.txt i el cache s\'actualitza quan s\'emmagatzema contingut traduït.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Quan Yoast SEO, Rank Math, All in One SEO o SEOPress està actiu, Lingua Forge suprimeix automàticament la seva sortida hreflang mitjançant un filtre. Els plugins SEO generals produeixen hreflang basat en una estructura d\'URL d\'un sol idioma i no poden tenir en compte la vostra configuració de rutes multilingües; la sortida de LF sempre és correcta.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Quin nivell de model utilitzar per a la traducció de pàgines completes. La qualitat utilitza el model configurat a la taula de models anterior i es recomana per a traduccions precises i de llarg format. Canvia a Llum només si la rapidesa o el cost són la prioritat i el contingut és curt.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Mentre està actiu, el plugin mu gestiona el conjunt bàsic d\'etiquetes OG i LF emet només etiquetes de localització (mode automàtic). Elimina\'l per passar automàticament a mode OG complet.','WooCommerce'=>'WooCommerce','WooCommerce product price'=>'Preu del producte WooCommerce','WooCommerce SEO settings saved.'=>'Configuració SEO de WooCommerce desada.','WooCommerce store currency'=>'Moneda de la botiga WooCommerce','Word count'=>' comptador de paraules','WP core canonical active (hreflang disabled)'=>'Canonical del nucli de WP actiu (hreflang desactivat)','WP-CLI reference'=>'Referència WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Escriu peticions i respostes d\'AI a disc per a la resolució de problemes','XML Sitemap'=>'Mapa del lloc XML','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'També pots definir claus com a constants o variables d\'entorn (per exemple, en wp-config.php). Aquestes fonts s\'utilitzen automàticament com a fallback quan no s\'emmagatzema cap clau de base de dades.','You do not have permission to manage these settings.'=>'No tens permís per gestionar aquestes configuracions.','You do not have permission to read this post.'=>'No tens permís per llegir aquesta publicació.','{n} stale path(s)'=>'{n} camí(s) obsolet(s)','~%d min read'=>'~%d min de lectura' . "\0" . '~%d min de lectura','— Any source language —'=>'— Qualsevol llengua d\'origen —','— Any target language —'=>'— Qualsevol llengua de destinació —','— Any target —'=>'— Qualsevol destinació —','— Any —'=>'— Qualsevol —','— auto-detect —'=>'— detecció automàtica —','— Deferred to plugin'=>'— S\'ha ajornat a plugin','— Disabled'=>'— Desactivat','— Not detected'=>'— No detectat','— select a language —'=>'— selecciona una llengua —','— toggle in Settings → Behavior.'=>'— commutador a Configuració → Comportament.','← Back'=>'← Enrere','↑ Detected from current post'=>'↑ Detectat a partir de la publicació actual','→ Locale tags only (manual setting)'=>'→ Etiquetes de localització només (configuració manual)','→ Locale tags only — deferring base OG to plugin'=>'→ Etiquetes de localització només — ajornant la base OG al plugin','↺ Re-translate'=>'↺ Re-traduir','↺ Refine'=>'↺ Refinar','↺ Refresh'=>'↺ Actualitza','↺ Refreshing…'=>'↺ Actualitzant…','⚠ Borderline'=>'⚠ Limítrof','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ No s\'han trobat publicacions <strong>{lang}</strong>. Assegura\'t que totes les publicacions traduïdes tenen el seu meta de llengua configurat com a <strong>{lang}</strong> a la metabox de llengua.','⚠ No changes'=>'⚠ No hi ha canvis','⚠ No changes — re-scan?'=>'⚠ No hi ha canvis — reescanejar?','✅ Fixed ({n})'=>'✅ Arreglat ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ No s\'han trobat enllaços trencats ni discrepàncies de plantilla per a <strong>{lang}</strong>. S\'han escanejat <strong>{scanned}</strong> publicació(s) i pàgina(s) — totes les comprovacions han passat. Els enllaços de la part de la plantilla (capçalera, peu de pàgina, barra lateral) no s\'inclouen aquí — utilitza el botó de Reparar parts de plantilla per comprovar-los per separat.','✅ Template fixed'=>'✅ Plantilla arreglada','✓ %s notified successfully.'=>'✓ %s notificat amb èxit.','✓ Active'=>'✓ Actiu','✓ Active at /lf-sitemap.xml'=>'✓ Actiu a /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Actiu — %d entrada d\'URL amb alternants de llengua' . "\0" . '✓ Actiu — %d entrades d\'URL amb alternants de llengua','✓ Active — full OG + Twitter Cards'=>'✓ Actiu — OG complet + Targetes de Twitter','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Actiu — Etiquetes de localització només (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Totes les parts creades.','✓ All templates created.'=>'✓ Totes les plantilles creades.','✓ All translated.'=>'✓ Totes traduïdes.','✓ Configured'=>'✓ Configurat','✓ Connection OK'=>'✓ Connexió OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Contingut generat — consulta la sobreposició per revisar, refinar i aplicar.','✓ Done'=>'✓ Fet','✓ Enabled'=>'✓ Activat','✓ Good length'=>'✓ Bona longitud','✓ Hreflang active'=>'✓ Hreflang actiu','✓ In safe storage'=>'✓ En emmagatzematge segur','✓ Language installed.'=>'✓ Idioma instal·lat.','✓ LF outputs'=>'✓ Sortides LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Sortides LF Article / WebPage / WebSite','✓ LF outputs full OG + Twitter Cards'=>'✓ Sortides LF OG complet + Targetes de Twitter','✓ LF outputs — plugin hreflang suppressed'=>'✓ Sortides LF — hreflang del plugin suprimida','✓ Links fixed.'=>'✓ Enllaços arreglats.','✓ Nav refs fixed.'=>'✓ Referències de navegació arreglades.','✓ Parts fixed.'=>'✓ Parts arreglades.','✓ Pattern translated.'=>'✓ Patró traduït.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Fitxer robots.txt físic trobat. La directiva Sitemap de LF està present.','✓ Refined — review the updated draft above.'=>'✓ Refinat — revisa l\'esborrany actualitzat a dalt.','✓ Translation saved'=>'✓ Traducció desada','✓ WP core canonical removed'=>'✓ Canonical del nucli de WP eliminat','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ Fallida del ping de %s. L\'URL del sitemap encara s\'anuncia en robots.txt — el motor de cerca el descobrirà en la seva propera exploració.','✗ Disabled'=>'✗ Desactivat','✗ Error:'=>'✗ Error:','✗ Failed:'=>'✗ Fallat:','✗ Not configured'=>'✗ No configurat','✗ Too long'=>'✗ Massa llarg','✗ Too short'=>'✗ Massa curt','❌ Failed'=>'❌ Fallat','📄 Wrong template'=>'📄 Plantilla incorrecta','📍 Stale path (page moved)'=>'📍 Camí obsolet (pàgina moguda)']];
